// Input: Gemini's structured output (item.json.output), plus context
// from earlier nodes for fields Gemini doesn't produce.

const data = $input.first().json.output ?? $input.first().json;

// ---- 1. Compute total score + verdict (n8n owns this, never the LLM) ----
const total_score =
  (data.market_potential_score || 0) +
  (data.execution_difficulty_score || 0) +
  (data.differentiation_score || 0) +
  (data.risk_level_score || 0);

let verdict;
if (total_score >= 70) verdict = "GO";
else if (total_score >= 40) verdict = "CONDITIONAL GO";
else verdict = "NO-GO";

// ---- 2. Compute confidence from whether live search data existed ----
// Pull the section-data flags saved by the earlier "format for Gemini" node
const formatNode = $('Format Searches').first().json; // adjust node name if different
const sectionsWithData = formatNode?.sections_with_data || [];

const marketSection = sectionsWithData.find(s => s.section === "Market Size & Trend");
const competitorSections = sectionsWithData.filter(s => s.section?.includes("Competitor"));

const hadMarketData = marketSection?.hasData ?? false;
const hadCompetitorData = competitorSections.some(s => s.hasData);

const confidence = (hadMarketData && hadCompetitorData) ? "Medium" : "Low";
// Note: bump to "High" only if you later add a manual/stronger check —
// per the template, Low is the safe default when either section lacked live data.

// ---- 3. Metadata ----
const report_id = `IVR-${Date.now()}`;
const generated_date = new Date().toISOString().split("T")[0];
const tool_name = "Tharun's Idea Validator Bot";

// Pull original idea + category if captured earlier in the pipeline
const plannerData = $('Extract Output').first().json;
const idea_one_liner = data.idea_restatement || "";
const category = plannerData?.category || "General";

// ---- 4. Competitor + risk array unpacking (template needs flat fields) ----
const comp = data.competitors || [];
const risks = data.risks || [];

const flat = {
  ...data,
  total_score,
  verdict,
  confidence,
  report_id,
  generated_date,
  category,
  idea_one_liner,

  input_quality_flag: "PASS",
  input_quality_reason: "",

  comp_1_name: comp[0]?.name || "N/A", comp_1_desc: comp[0]?.desc || "", comp_1_strength: comp[0]?.strength || "", comp_1_weakness: comp[0]?.weakness || "", comp_1_gap: comp[0]?.gap || "",
  comp_2_name: comp[1]?.name || "N/A", comp_2_desc: comp[1]?.desc || "", comp_2_strength: comp[1]?.strength || "", comp_2_weakness: comp[1]?.weakness || "", comp_2_gap: comp[1]?.gap || "",
  comp_3_name: comp[2]?.name || "N/A", comp_3_desc: comp[2]?.desc || "", comp_3_strength: comp[2]?.strength || "", comp_3_weakness: comp[2]?.weakness || "", comp_3_gap: comp[2]?.gap || "",

  competitor_source_flag: hadCompetitorData ? "Live search" : "Model knowledge only",

  risk_1: risks[0]?.risk || "", likelihood_1: risks[0]?.likelihood || "", impact_1: risks[0]?.impact || "", mitigation_1: risks[0]?.mitigation || "",
  risk_2: risks[1]?.risk || "", likelihood_2: risks[1]?.likelihood || "", impact_2: risks[1]?.impact || "", mitigation_2: risks[1]?.mitigation || "",
  risk_3: risks[2]?.risk || "", likelihood_3: risks[2]?.likelihood || "", impact_3: risks[2]?.impact || "", mitigation_3: risks[2]?.mitigation || "",

  source_1: data.sources?.[0] || "No external sources used — analysis based on model reasoning only.",
  source_2: data.sources?.[1] || "",
  source_3: data.sources?.[2] || "",

  tool_name
};

return [{ json: flat }];

// Input: merged output — one item per Tavily search branch, in order.
// Each Tavily node's output typically has a `results` array with
// {title, url, content} per result. Adjust field names if your
// Tavily node version differs.

const items = $input.all();

const LABELS = [
  "Market Size & Trend",
  "Target Audience / ICP",
  "Pricing Landscape",
  "Competitor 1 Detail",
  "Competitor 2 Detail",
  "Competitor 3 Detail + Category News"
];

const MAX_RESULTS_PER_SECTION = 4;
const MAX_CONTENT_CHARS = 600; // trims any single result's snippet

function formatSection(label, tavilyOutput) {
  const results = tavilyOutput?.results || tavilyOutput?.json?.results || [];
  if (!results.length) {
    return `## ${label}\n(No search results returned for this section.)\n`;
  }

  const lines = results.slice(0, MAX_RESULTS_PER_SECTION).map((r, i) => {
    const content = (r.content || r.snippet || "").slice(0, MAX_CONTENT_CHARS);
    return `${i + 1}. ${r.title || "Untitled"} (${r.url || "no url"})\n   ${content}`;
  });

  return `## ${label}\n${lines.join("\n")}\n`;
}

// Pull competitor names + original idea text from earlier in the workflow
const plannerData = $('Extract Output').first().json;
const ideaText = $('Extract Validation').first().json.idea_text
  || $('Trigger').first().json.message.text
  || "";

let contextBlock = `# IDEA\n${ideaText}\n\n`;

contextBlock += `# COMPETITORS IDENTIFIED\n`;
contextBlock += (plannerData.competitors || [])
  .map((c, i) => `${i + 1}. ${c.name}`)
  .join("\n") || "None identified.";
contextBlock += "\n\n";

contextBlock += `# RESEARCH FINDINGS\n\n`;
items.forEach((item, i) => {
  contextBlock += formatSection(LABELS[i] || `Section ${i + 1}`, item.json) + "\n";
});

// Track which sections actually had live data — feeds the confidence field later
const sectionsWithData = items.map((item, i) => ({
  section: LABELS[i],
  hasData: (item.json?.results || item.json?.json?.results || []).length > 0
}));

return [{
  json: {
    context_block: contextBlock,
    sections_with_data: sectionsWithData,
    competitor_exist: plannerData.competitor_exist,
    competitors: plannerData.competitors
  }
}];

const raw = $input.first().json.output ?? $input.first().json;

let data;
try {
  data = typeof raw === "string" ? JSON.parse(raw) : raw;
} catch (err) {
  throw new Error("Failed to parse agent output as JSON: " + String(raw).slice(0, 300));
}

const kw = {
  keyword_search1: data.keyword_search1 || [],
  keyword_search2: data.keyword_search2 || [],
  keyword_search3: data.keyword_search3 || [],
  keyword_search4: data.keyword_search4 || [],
  keyword_search5: data.keyword_search5 || [],
  keyword_search6: data.keyword_search6 || []
};

const competitors = Array.isArray(data.competitors) ? data.competitors : [];
const competitorExist = !!data.competitor_exist && competitors.length > 0;

const joinQuery = (arr) => arr.filter(Boolean).join(" ");

const FIXED_SUFFIX = {
  market: "market size TAM SAM growth trend statistics 2026",
  icp: "target customer ideal customer profile buyer persona pain points",
  pricing: "pricing plans cost comparison subscription tiers",
  competitor: "strengths weaknesses user reviews complaints pricing",
  competitorNews: "strengths weaknesses user reviews recent funding news traction"
};

const buildQuery = (arr, suffix, fallbackPrefix) => {
  const kwPart = joinQuery(arr);
  const prefix = kwPart || fallbackPrefix || "";
  return `${prefix} ${suffix}`.trim();
};

return [{
  json: {
    competitor_exist: competitorExist,
    competitors,
    query1: buildQuery(kw.keyword_search1, FIXED_SUFFIX.market),
    query2: buildQuery(kw.keyword_search2, FIXED_SUFFIX.icp),
    query3: buildQuery(kw.keyword_search3, FIXED_SUFFIX.pricing),
    query4: buildQuery(kw.keyword_search4, FIXED_SUFFIX.competitor, competitors[0]?.name || ""),
    query5: buildQuery(kw.keyword_search5, FIXED_SUFFIX.competitor, competitors[1]?.name || ""),
    query6: buildQuery(kw.keyword_search6, FIXED_SUFFIX.competitorNews, competitors[2]?.name || "")
  }
}];

// Extract the JSON content from Groq API response
const content = $input.first().json.choices?.[0]?.message?.content;

// Parse and return
try {
  const parsed = JSON.parse(content);
  return [{ json: parsed }];
} catch (err) {
  return [{
    json: {
      error: true,
      message: "Failed to parse LLM response",
      raw: content
    }
  }];
}

