const data = $input.first().json;
const d = Array.isArray(data) ? data[0] : data;

function safe(v) {
  if (v === undefined || v === null || v === "") return "Not available";
  return String(v);
}

const TEMPLATE = `# Idea Validation Report — Standard Form (v2)

## Idea Validation Report

