### 13. Recommended Next Steps

1. {next_step_1}
2. {next_step_2}
3. {next_step_3}

---

### 14. Sources

- {source_1}
- {source_2}
- {source_3}

---

*Generated by {tool_name} — AI-generated analysis, not financial or investment advice.*
`;

let md = TEMPLATE;
for (const [key, value] of Object.entries(d)) {
  const placeholder = new RegExp(`\\{${key}\\}`, "g");
  md = md.replace(placeholder, safe(value));
}

const buffer = Buffer.from(md, "utf8");

return [
  {
    json: {
      report_id: d.report_id,
      verdict: d.verdict,
      total_score: d.total_score,
      filename: `idea-validation-${d.report_id || "report"}.md`
    },
    binary: {
      data: await this.helpers.prepareBinaryData(
        buffer,
        `idea-validation-${d.report_id || "report"}.md`,
        "text/markdown"
      )
    }
  }
];
